'use client';
import {useEffect,useMemo,useState} from 'react';
import {Home,CalendarDays,PartyPopper,Wallet,UserRound,Plus,ChevronLeft,ChevronRight,Users,MapPin,Clock,ArrowUpRight,ArrowDownLeft,Copy,Check,LogOut,Search, X, Sparkles, CircleDollarSign, Menu, CalendarPlus, CreditCard, Link2, SlidersHorizontal, Bell, Moon, Sun, QrCode, ShieldCheck, Smartphone} from 'lucide-react';

type AnyObj=Record<string,any>;
const money=(c:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((c||0)/100);
const dateFmt=(d:string|Date,options:Intl.DateTimeFormatOptions)=>new Intl.DateTimeFormat('pt-BR',options).format(new Date(d));
const nav=[['Home',Home],['Calendário',CalendarDays],['Eventos',PartyPopper],['Gastos',Wallet],['Perfil',UserRound]] as const;
const demoPeople=['Igor','João','Pedro','Lucas','Mariana'];
function Avatar({name,size='md'}:{name:string,size?:'sm'|'md'|'lg'}){const colors=['bg-sky-100 text-sky-700','bg-rose-100 text-rose-700','bg-orange-100 text-orange-700','bg-amber-100 text-amber-700','bg-emerald-100 text-emerald-700'];let ix=Math.max(0,demoPeople.indexOf(name));return <span className={`inline-flex shrink-0 items-center justify-center rounded-full font-semibold ${colors[ix%colors.length]} ${size==='sm'?'h-7 w-7 text-[10px]':size==='lg'?'h-12 w-12 text-sm':'h-9 w-9 text-xs'}`}>{name.split(' ').map(s=>s[0]).join('').slice(0,2)}</span>}
function BrandName({large=false}:{large?:boolean}){return <span className={`brand-name ${large?'brand-name-large':''}`} aria-label="casaê">casa<span>ê</span></span>}
function Button({children,onClick,variant='primary',className=''}:{children:React.ReactNode,onClick?:()=>void,variant?:'primary'|'soft'|'plain',className?:string}){return <button onClick={onClick} className={`inline-flex items-center justify-center gap-2 rounded-2xl px-4 py-3 text-sm font-semibold transition active:scale-[.98] ${variant==='primary'?'bg-[#347f9f] text-white shadow-[0_6px_16px_#347f9f33] hover:bg-[#286781]':variant==='soft'?'bg-[#e5f1f4] text-[#286781] hover:bg-[#d6e8ed]':'text-slate-500 hover:bg-slate-100'} ${className}`}>{children}</button>}
function Field({label,...props}:{label:string;[key:string]:any}){return <label className="block text-sm font-medium text-slate-600">{label}<input {...props} className="mt-1.5 w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-[15px] text-slate-800 outline-none transition placeholder:text-slate-400 focus:border-sky-400 focus:ring-4 focus:ring-sky-100"/></label>}
export default function Page(){
 const [section,setSection]=useState('Home'),[data,setData]=useState<AnyObj|null>(null),[loading,setLoading]=useState(true),[authMode,setAuthMode]=useState('login'),[authError,setAuthError]=useState(''),[modal,setModal]=useState(''),[month,setMonth]=useState(new Date()),[selectedDay,setSelectedDay]=useState<number|null>(null),[findFree,setFindFree]=useState(false),[filter,setFilter]=useState('Todos'),[toast,setToast]=useState(''),[selectedEvent,setSelectedEvent]=useState(0),[notifications,setNotifications]=useState<AnyObj[]>([]),[unread,setUnread]=useState(0),[oauthMessage,setOauthMessage]=useState('');
 const refresh=()=>fetch('/api/bootstrap').then(r=>r.ok?r.json():null).then(d=>setData(d)).finally(()=>setLoading(false));
 useEffect(()=>{refresh();const params=new URLSearchParams(location.search),q=params.get('oauth');if(params.get('section')==='Notificações')setSection('Notificações');if(q)setOauthMessage(q.includes('config')?'O login social precisa ser configurado no ambiente.':'Não foi possível concluir o login social.')},[]);
 useEffect(()=>{if(!data?.user?.id)return;const load=()=>fetch('/api/notifications').then(r=>r.ok?r.json():null).then(d=>{if(d){setNotifications(d.items);setUnread(d.unread)}});load();const timer=setInterval(load,60000);if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});return()=>clearInterval(timer)},[data?.user?.id]);
 useEffect(()=>{if(!data?.user?.id)return;fetch('/api/preferences').then(r=>r.ok?r.json():null).then(p=>{if(!p)return;localStorage.setItem('junto-theme',p.theme.toLowerCase());applyTheme(p.theme)}).catch(()=>{})},[data?.user?.id]);
 function applyTheme(theme:string){const dark=theme==='DARK'||(theme==='SYSTEM'&&window.matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.classList.toggle('dark',dark)}
 useEffect(()=>{const media=window.matchMedia('(prefers-color-scheme: dark)');const update=()=>{if(localStorage.getItem('junto-theme')==='system')applyTheme('SYSTEM')};media.addEventListener('change',update);return()=>media.removeEventListener('change',update)},[]);
 const notify=(t:string)=>{setToast(t);setTimeout(()=>setToast(''),2600)};
 async function act(action:string,values:AnyObj={}){const r=await fetch('/api/action',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,groupId:data?.group?.id,...values})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Não foi possível salvar');await refresh();return j}
 async function auth(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setAuthError('');const form=new FormData(e.currentTarget);const payload=Object.fromEntries(form.entries());if(authMode==='register'&&payload.password!==payload.confirm) {setAuthError('As senhas não coincidem.');return}const r=await fetch('/api/auth/'+(authMode==='register'?'register':'login'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const j=await r.json();if(!r.ok){setAuthError(j.error);return}await refresh()}
 const group=data?.group,people=group?.members?.map((m:AnyObj)=>m.user)||[];const visiblePeople=filter==='Todos'?people:filter==='Somente eu'?people.filter((p:AnyObj)=>p.id===data?.user?.id):people.filter((p:AnyObj)=>p.name===filter);
 const monthLabel=dateFmt(month,{month:'long',year:'numeric'});
 const dayCount=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),offset=(new Date(month.getFullYear(),month.getMonth(),1).getDay()+6)%7;
 const statusFor=(day:number)=>{const members=filter==='Todos'?people:filter==='Somente eu'?people.filter((p:AnyObj)=>p.id===data?.user?.id):people.filter((p:AnyObj)=>p.name===filter);if(!members.length)return {free:0,busy:0,total:0,state:'partial'};const dt=new Date(month.getFullYear(),month.getMonth(),day,12);const dayKey=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0');const manual=group.availability.filter((a:AnyObj)=>String(a.date).slice(0,10)===dayKey);const commitments=group.commitments.filter((c:AnyObj)=>new Date(c.startsAt).toDateString()===dt.toDateString());const states=members.map((m:AnyObj)=>{const answer=manual.find((a:AnyObj)=>a.userId===m.id);if(answer)return answer.status;return commitments.some((c:AnyObj)=>c.userId===m.id)?'BUSY':'MAYBE'});const free=states.filter((s:string)=>s==='FREE').length,busy=states.filter((s:string)=>s==='BUSY').length;return {free,busy,total:members.length,state:free===members.length?'free':busy===members.length?'busy':'partial'}}
 const freeDays=Array.from({length:dayCount},(_,i)=>i+1).filter(d=>statusFor(d)?.state==='free');
 const events=group?.events||[],event=events[Math.min(selectedEvent,Math.max(events.length-1,0))];const expenses=event?.expenses||[];
 const gross=expenses.reduce((n:number,e:AnyObj)=>n+e.amountCents,0);
 const tabs=nav;
 if(loading)return <main className="grid min-h-screen place-items-center text-sky-600"><div className="animate-pulse text-lg font-semibold">casaê</div></main>;
 if(!data)return <main className="min-h-screen px-5 py-12"><div className="mx-auto max-w-md rounded-[2rem] bg-white p-7 shadow-xl shadow-slate-200/60"><div className="mb-8 flex items-center gap-3"><span className="brand-mark grid h-14 w-14 place-items-center overflow-hidden rounded-[20px]"><img src="/icons/icon-192.svg" alt="" className="h-full w-full"/></span><div><BrandName large/><p className="mt-0.5 text-xs font-medium tracking-wide text-slate-500">planos que acontecem</p></div></div><h1 className="text-3xl font-bold tracking-tight">{authMode==='register'?'Seus planos começam aqui.':'Que bom ter você de volta.'}</h1><p className="mt-2 mb-7 text-slate-500">Organize os planos com quem faz parte deles.</p><form onSubmit={auth} className="space-y-4">{authMode==='register'&&<Field label="Seu nome" name="name" placeholder="Como podemos te chamar?" required/>}<Field label="E-mail" name="email" type="email" placeholder="voce@email.com" required/><Field label="Senha" name="password" type="password" placeholder="Pelo menos 8 caracteres" required/>{authMode==='register'&&<Field label="Confirme sua senha" name="confirm" type="password" placeholder="Repita sua senha" required/>}{authError&&<p className="text-sm text-rose-600">{authError}</p>}<Button className="w-full">{authMode==='register'?'Criar minha conta':'Entrar'}</Button></form>{oauthMessage&&<p className="mt-3 text-center text-sm text-amber-700">{oauthMessage}</p>}{authMode==='login'&&<div className="mt-4 grid grid-cols-2 gap-2"><a href="/api/auth/google" className="flex items-center justify-center gap-2 rounded-2xl border border-slate-200 py-3 text-sm font-semibold text-slate-700 hover:bg-slate-50">G Google</a><a href="/api/auth/apple" className="flex items-center justify-center gap-2 rounded-2xl border border-slate-200 py-3 text-sm font-semibold text-slate-700 hover:bg-slate-50"> Apple</a></div>}<button onClick={()=>setAuthMode(authMode==='register'?'login':'register')} className="mt-6 w-full text-center text-sm font-medium text-sky-700">{authMode==='register'?'Já tenho uma conta · Entrar':'Criar conta gratuita'}</button><p className="mt-4 text-center text-xs text-slate-400">Esqueceu a senha? A recuperação por e-mail será habilitada com o serviço de envio na próxima configuração.</p></div></main>;
 const invite=async()=>{await navigator.clipboard?.writeText(location.origin+'/convite/'+group.inviteCode);notify('Link do convite copiado!')};
 const labelDay=selectedDay?new Date(month.getFullYear(),month.getMonth(),selectedDay,12):new Date();
 const changeMonth=(step:number)=>setMonth(new Date(month.getFullYear(),month.getMonth()+step,1));
 return <main className="min-h-screen bg-[#f8f8f4] pb-24 md:pb-8">
  <header className="app-header sticky top-0 z-30 border-b border-slate-200/70 bg-[#fbfaf7]/90 backdrop-blur-xl"><div className="mx-auto flex h-[76px] max-w-7xl items-center justify-between px-4 sm:px-7"><div className="brand-lockup flex items-center gap-2.5"><span className="brand-mark grid h-12 w-12 place-items-center overflow-hidden rounded-[17px]"><img src="/icons/icon-192.svg" alt="" className="h-full w-full"/></span><div className="leading-none"><BrandName/><span className="brand-tagline mt-1 block text-[9px] font-semibold uppercase tracking-[.16em]">planos que acontecem</span></div></div><div className="hidden items-center gap-1 rounded-2xl bg-white/80 p-1 md:flex">{tabs.map(([t,I])=><button onClick={()=>setSection(t)} className={`flex items-center gap-2 rounded-xl px-3 py-2 text-sm font-medium ${section===t?'bg-[#e8f3f6] text-sky-700':'text-slate-500 hover:text-slate-800'}`} key={t}><I size={16}/>{t}</button>)}</div><div className="flex items-center gap-3"><button className="hidden h-10 items-center gap-2 rounded-2xl bg-white px-3 text-sm font-semibold text-slate-700 sm:flex" onClick={()=>setModal('group')}>{group?.emoji||'👋'} {group?.name||'Criar grupo'}<ChevronRight size={15}/></button><button onClick={async()=>{setSection('Notificações');const r=await fetch('/api/notifications');if(r.ok){const n=await r.json();setNotifications(n.items);setUnread(n.unread)}}} aria-label="Notificações" className="relative grid h-10 w-10 place-items-center rounded-2xl bg-white text-slate-600"><Bell size={18}/>{unread>0&&<span className="absolute right-1 top-1 h-2.5 w-2.5 rounded-full bg-rose-500 ring-2 ring-white"/>}</button><button onClick={()=>setSection('Perfil')} aria-label="Abrir perfil"><Avatar name={data.user.name}/></button></div></div></header>
  <div className="mx-auto grid max-w-7xl gap-6 px-4 py-6 sm:px-7 lg:grid-cols-[minmax(0,1fr)_310px] lg:py-9">
   <section className="min-w-0">
    {section==='Home'&&<><div className="home-welcome mb-7 flex items-end justify-between overflow-hidden rounded-[30px] p-5 sm:p-7"><div className="relative z-10"><span className="welcome-kicker mb-3 inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-[10px] font-bold uppercase tracking-[.15em]"><Sparkles size={12}/> seu espaço para combinar</span><p className="mb-1 text-sm font-medium text-white/75">{dateFmt(new Date(),{weekday:'long',day:'numeric',month:'long'})}</p><h1 className="text-[28px] font-semibold tracking-[-.045em] text-white sm:text-4xl">Olá, {data.user.name.split(' ')[0]} <span>👋</span></h1><p className="mt-2 text-sm text-white/80 sm:text-base">Os bons planos começam quando todo mundo se encontra.</p></div><div className="relative z-10 hidden sm:block"><span className="welcome-stamp"><img src="/icons/icon-192.svg" alt=""/></span></div><Button variant="soft" onClick={()=>setModal('invite')} className="relative z-10 hidden !bg-white/95 !text-[#286781] sm:inline-flex"><Users size={16}/> Convidar amigos</Button></div><div className="grid gap-4 sm:grid-cols-3"><Stat icon={CalendarDays} title="Dias livres" value={freeDays.length?String(freeDays.length):'—'} foot={"em "+dateFmt(month,{month:"long"})} tone="sky"/><Stat icon={PartyPopper} title="Próximo rolê" value={event?.title||'Criar evento'} foot={event?dateFmt(event.startsAt,{day:'numeric',month:'short'}):'Seu grupo está esperando'} tone="peach"/><Stat icon={Wallet} title="Gastos do evento" value={money(gross)} foot={expenses.length+' despesas registradas'} tone="mint"/></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><article className="rounded-[28px] bg-white p-5 shadow-sm shadow-slate-200/60 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-lg font-bold">Seu calendário</h2><p className="mt-1 text-sm text-slate-500">Disponibilidade do grupo</p></div><Button variant="plain" onClick={()=>setSection('Calendário')}>Ver mês <ChevronRight size={16}/></Button></div><MiniCalendar month={month} changeMonth={changeMonth} dayCount={dayCount} offset={offset} statusFor={statusFor} onDay={setSelectedDay} selectedDay={selectedDay} freeDays={freeDays}/></article><div className="space-y-5"><article className="overflow-hidden rounded-[28px] bg-gradient-to-br from-[#4b94b3] via-[#397f9f] to-[#2b6079] p-5 text-white shadow-lg shadow-sky-200/70"><div className="flex items-start justify-between"><span className="rounded-full bg-white/15 px-3 py-1 text-[11px] font-semibold tracking-wide">PRÓXIMO EVENTO</span><span className="text-2xl">{event?.emoji||'🎆'}</span></div><h2 className="mt-5 text-xl font-bold">{event?.title||'Seu próximo evento'}</h2><p className="mt-1 text-sm text-white/75">{event?.location||'Adicione um evento para começar'}</p><div className="my-5 h-px bg-white/20"/><p className="text-sm text-white/80">{event?dateFmt(event.startsAt,{day:'2-digit',month:'short',year:'numeric'}):'Um plano legal está por vir'}</p><Button variant="soft" className="mt-4 w-full !bg-white !text-sky-700" onClick={()=>setSection('Eventos')}>Ver evento <ArrowUpRight size={16}/></Button></article><article className="rounded-[28px] bg-white p-5 shadow-sm shadow-slate-200/60"><div className="mb-4 flex items-center justify-between"><h2 className="font-bold">Próximos compromissos</h2><button onClick={()=>setModal('commitment')} className="grid h-8 w-8 place-items-center rounded-xl bg-sky-50 text-sky-700"><Plus size={17}/></button></div>{(group?.commitments||[]).slice(0,3).map((c:AnyObj)=><div className="mb-3 flex items-center gap-3" key={c.id}><div className="grid h-10 w-10 place-items-center rounded-2xl bg-amber-50 text-amber-600"><Clock size={17}/></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{c.title}</p><p className="text-xs text-slate-500">{dateFmt(c.startsAt,{day:'numeric',month:'short'})} · {c.user?.name}</p></div></div>)}{!group?.commitments?.length&&<p className="py-3 text-sm text-slate-500">Sem compromissos por enquanto.</p>}<Button variant="plain" className="mt-1 !px-0 !py-2" onClick={()=>setSection('Calendário')}>Abrir calendário <ChevronRight size={15}/></Button></article></div></div><article className="mt-5 rounded-[28px] bg-white p-5 shadow-sm shadow-slate-200/60 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-sm text-slate-500">Seu grupo</p><h2 className="mt-1 text-lg font-bold">{group?.emoji} {group?.name}</h2></div><button onClick={()=>setModal('invite')} className="flex h-10 items-center gap-2 rounded-2xl bg-[#e8f3f6] px-4 text-sm font-semibold text-sky-700"><Plus size={15}/> Convidar</button></div><People people={people}/></article></>}
    {section==='Calendário'&&<><div className="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p className="text-sm text-slate-500">Planejamento compartilhado</p><h1 className="mt-1 text-3xl font-bold tracking-tight">Calendário</h1></div><Button onClick={()=>setModal('commitment')}><Plus size={17}/> Compromisso</Button></div><div className="mb-4 flex flex-wrap items-center gap-2"><select value={filter} onChange={e=>setFilter(e.target.value)} className="rounded-xl border-0 bg-white px-3 py-2.5 text-sm font-medium text-slate-600 shadow-sm"><option>Todos</option><option>Somente eu</option>{people.map((p:AnyObj)=><option key={p.id}>{p.name}</option>)}</select><button onClick={()=>setFindFree(!findFree)} className={`flex items-center gap-2 rounded-xl px-3 py-2.5 text-sm font-semibold ${findFree?'bg-emerald-100 text-emerald-800':'bg-white text-slate-600'}`}><Sparkles size={16}/> Encontrar dias livres</button></div><article className="rounded-[28px] bg-white p-5 shadow-sm sm:p-7"><div className="mb-6 flex items-center justify-between"><button onClick={()=>changeMonth(-1)} className="grid h-10 w-10 place-items-center rounded-2xl bg-slate-50 text-slate-600"><ChevronLeft size={20}/></button><div className="text-center"><h2 className="text-lg font-bold capitalize">{monthLabel}</h2><p className="mt-1 text-xs text-slate-500">{group?.name}</p></div><button onClick={()=>changeMonth(1)} className="grid h-10 w-10 place-items-center rounded-2xl bg-slate-50 text-slate-600"><ChevronRight size={20}/></button></div><CalendarGrid dayCount={dayCount} offset={offset} statusFor={statusFor} onDay={setSelectedDay} selectedDay={selectedDay} findFree={findFree} freeDays={freeDays}/><Legend/><div className="mt-6 flex flex-wrap gap-2 border-t border-slate-100 pt-5"><Button variant="soft" onClick={()=>act('availability',{date:`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}-${String(selectedDay||new Date().getDate()).padStart(2,'0')}`,status:'FREE'}).then(()=>notify('Disponibilidade marcada como livre')).catch(e=>notify(e.message))}>✓ Marcar livre</Button><Button variant="plain" onClick={()=>act('availability',{date:`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}-${String(selectedDay||new Date().getDate()).padStart(2,'0')}`,status:'BUSY'}).then(()=>notify('Disponibilidade atualizada')).catch(e=>notify(e.message))}>Marcar ocupado</Button><Button variant="plain" onClick={()=>act('availability',{date:`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}-${String(selectedDay||new Date().getDate()).padStart(2,'0')}`,status:'MAYBE'}).then(()=>notify('Disponibilidade marcada como talvez')).catch(e=>notify(e.message))}>Talvez</Button></div></article>{selectedDay&&<DayDetail date={labelDay} group={group} people={visiblePeople} statusFor={statusFor} selectedDay={selectedDay}/>}</>}
    {section==='Eventos'&&<><div className="mb-6 flex items-end justify-between"><div><p className="text-sm text-slate-500">Planos que viram história</p><h1 className="mt-1 text-3xl font-bold tracking-tight">Eventos</h1></div><Button onClick={()=>setModal('event')}><Plus size={17}/> Novo evento</Button></div>{events.length===0?<Empty icon={PartyPopper} title="Seu próximo plano começa aqui" action="Criar evento" onClick={()=>setModal('event')}/>:<div className="space-y-5">{events.map((ev:AnyObj,i:number)=><div key={ev.id} onClick={()=>setSelectedEvent(i)} className={`cursor-pointer overflow-hidden rounded-[30px] bg-gradient-to-br from-[#4b94b3] to-[#2b6079] p-6 text-white shadow-lg shadow-sky-200/70 transition hover:-translate-y-0.5 sm:p-8 ${i===selectedEvent?'ring-4 ring-sky-200':''}`}><div className="flex items-start justify-between"><span className="rounded-full bg-white/15 px-3 py-1 text-xs font-semibold">{group.name}</span><span className="text-4xl">{ev.emoji||'🎉'}</span></div><h2 className="mt-7 text-2xl font-bold">{ev.title}</h2><p className="mt-2 flex items-center gap-1.5 text-sm text-white/80"><MapPin size={15}/>{ev.location||'Local a definir'}</p><div className="mt-6 flex flex-wrap items-center justify-between gap-3 border-t border-white/20 pt-5"><div><p className="text-xs text-white/70">{dateFmt(ev.startsAt,{day:'2-digit',month:'short'})}{ev.endsAt?' — '+dateFmt(ev.endsAt,{day:'2-digit',month:'short'}):''}</p><p className="mt-1 text-lg font-bold">{Math.max(0,Math.ceil((new Date(ev.startsAt).getTime()-Date.now())/86400000))} dias para o encontro</p></div><div className="flex -space-x-2">{(ev.members||[]).slice(0,5).map((m:AnyObj)=><span key={m.user.id} className="rounded-full ring-2 ring-sky-600"><Avatar name={m.user.name} size="sm"/></span>)}</div></div></div>)}{event&&<EventFinance event={event} expenses={expenses} gross={gross} people={people} act={act} notify={notify}/>}<AuditTimeline items={group.auditLogs||[]} eventId={event?.id}/></div>}</>}
    {section==='Gastos'&&<><div className="mb-6 flex items-end justify-between"><div><p className="text-sm text-slate-500">Tudo às claras, sem planilha</p><h1 className="mt-1 text-3xl font-bold tracking-tight">Gastos</h1></div>{event&&<Button onClick={()=>setModal('expense')}><Plus size={17}/> Adicionar gasto</Button>}</div>{event?<><FinanceSummary expenses={expenses} gross={gross} people={people}/><MyFinancialSnapshot events={events} userId={data.user.id}/><article className="mt-5 rounded-[28px] bg-white p-5 shadow-sm sm:p-7"><h2 className="text-lg font-bold">Extrato do evento</h2><p className="mt-1 text-sm text-slate-500">Despesas originais e divisão por participante.</p><ExpenseList expenses={expenses}/><div className="mt-6 rounded-2xl bg-sky-50 p-4"><p className="font-semibold text-sky-950">Compensação automática</p><p className="mt-1 text-sm text-sky-800">As dívidas são somadas por pessoa e compensadas entre si para mostrar só o saldo líquido. O histórico das despesas originais permanece intacto.</p></div></article><NetBalances expenses={expenses} payments={event.payments||[]} eventId={event.id} people={people} me={data.user.id} act={act} notify={notify}/></>:<Empty icon={Wallet} title="Nenhum evento com despesas" action="Criar evento" onClick={()=>setModal('event')}/>}</>}
    {section==='Notificações'&&<NotificationCenter items={notifications} unread={unread} onRead={async(id)=>{await fetch('/api/notifications',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(id?{action:'read',id}:{action:'read-all'})});const r=await fetch('/api/notifications');if(r.ok){const n=await r.json();setNotifications(n.items);setUnread(n.unread)}}}/> }
    {section==='Perfil'&&<><div className="mb-6"><p className="text-sm text-slate-500">Sua conta e preferências</p><h1 className="mt-1 text-3xl font-bold tracking-tight">Perfil</h1></div><article className="rounded-[28px] bg-white p-6 shadow-sm"><div className="flex items-center gap-4"><Avatar name={data.user.name} size="lg"/><div><h2 className="text-lg font-bold">{data.user.name}</h2><p className="text-sm text-slate-500">{data.user.email}</p></div></div><ProfileForm user={data.user} act={act} notify={notify}/><div className="mt-8 border-t border-slate-100 pt-5"><h3 className="font-bold">Seu grupo</h3><p className="mt-1 text-sm text-slate-500">{group?.name} · {people.length} participantes</p><Button variant="soft" className="mt-4" onClick={()=>setModal('invite')}><Link2 size={16}/> Link de convite</Button></div><PreferencesForm userId={data.user.id} notify={notify} onTheme={applyTheme}/><button onClick={async()=>{await fetch('/api/auth/logout',{method:'POST'});setData(null)}} className="mt-8 flex items-center gap-2 text-sm font-semibold text-rose-600"><LogOut size={16}/> Sair da conta</button></article></>}
   </section>
   <aside className="hidden space-y-5 lg:block"><article className="rounded-[28px] bg-white p-5 shadow-sm"><div className="mb-4 flex items-center justify-between"><h2 className="font-bold">Seu grupo</h2><button onClick={()=>setModal('invite')} className="text-sky-700"><Plus size={18}/></button></div><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-sky-50 text-xl">{group?.emoji}</span><div><p className="text-sm font-bold">{group?.name}</p><p className="text-xs text-slate-500">{people.length} participantes</p></div></div><People people={people}/><Button variant="soft" className="mt-4 w-full" onClick={()=>setModal('invite')}><Users size={16}/> Convidar amigos</Button></article><article className="rounded-[28px] bg-white p-5 shadow-sm"><h2 className="mb-4 font-bold">Dias livres do grupo</h2><MiniCalendar month={month} changeMonth={changeMonth} dayCount={dayCount} offset={offset} statusFor={statusFor} onDay={setSelectedDay} selectedDay={selectedDay} freeDays={freeDays}/><Legend/></article><article className="rounded-[28px] bg-[#e8f3f6] p-5"><div className="flex items-center gap-2 text-sky-800"><Sparkles size={17}/><p className="text-sm font-bold">Feito pra combinar</p></div><p className="mt-2 text-sm leading-relaxed text-sky-900/75">Encontre um dia livre, monte o plano e deixe a divisão dos gastos com a gente.</p></article></aside>
  </div><nav className="safe-bottom fixed inset-x-0 bottom-0 z-40 border-t border-slate-200/70 bg-white/95 px-2 pt-2 pb-2 backdrop-blur-xl md:hidden"><div className="mx-auto flex max-w-md justify-around">{tabs.map(([t,I])=><button key={t} onClick={()=>setSection(t)} className={`flex min-w-[58px] flex-col items-center gap-1 rounded-xl px-2 py-1.5 text-[10px] font-semibold ${section===t?'text-sky-700':'text-slate-400'}`}><I size={20} strokeWidth={section===t?2.4:1.8}/>{t}</button>)}</div></nav>
  {selectedDay&&section==='Calendário'&&<Modal title={dateFmt(labelDay,{day:'numeric',month:'long'})} close={()=>setSelectedDay(null)}><DayDetail date={labelDay} group={group} people={visiblePeople} statusFor={statusFor} selectedDay={selectedDay}/><Button className="mt-4 w-full" onClick={()=>setModal('commitment')}>Adicionar compromisso</Button></Modal>}
  {modal&&<Modal title={modal==='invite'?'Convidar amigos':modal==='group'?'Seu grupo':modal==='commitment'?'Novo compromisso':modal==='event'?'Criar evento':'Adicionar gasto'} close={()=>setModal('')}>
   {modal==='invite'&&<div><p className="text-sm leading-relaxed text-slate-500">Compartilhe o link para seus amigos entrarem em <b>{group?.name}</b>.</p><div className="my-5 flex items-center gap-2 rounded-2xl bg-slate-50 p-3"><code className="min-w-0 flex-1 truncate text-xs text-slate-600">{typeof location!=='undefined'?location.origin:''}/convite/{group?.inviteCode}</code><button onClick={invite} className="grid h-10 w-10 place-items-center rounded-xl bg-sky-600 text-white"><Copy size={16}/></button></div><Button className="w-full" onClick={invite}><Copy size={16}/> Copiar link</Button><InviteByEmail group={group} act={act} notify={notify}/></div>}
   {modal==='group'&&<GroupForm act={act} refresh={refresh} notify={notify} onDone={()=>setModal('')}/>}
   {modal==='commitment'&&<CommitmentForm act={act} notify={notify} onDone={()=>setModal('')}/>}
   {modal==='event'&&<EventForm act={act} notify={notify} onDone={()=>setModal('')}/>}
   {modal==='expense'&&event&&<ExpenseForm event={event} people={people} act={act} notify={notify} onDone={()=>setModal('')}/>}
  </Modal>}
  {toast&&<div className="fixed bottom-24 left-1/2 z-[60] -translate-x-1/2 rounded-2xl bg-slate-900 px-5 py-3 text-sm font-medium text-white shadow-xl md:bottom-6">{toast}</div>}
 </main>
}
function Stat({icon:Icon,title,value,foot,tone}:{icon:any,title:string,value:string,foot:string,tone:string}){const bg=tone==='sky'?'bg-sky-100 text-sky-700':tone==='peach'?'bg-orange-100 text-orange-700':'bg-emerald-100 text-emerald-700';return <article className="rounded-[24px] bg-white p-4 shadow-sm shadow-slate-200/60 sm:p-5"><div className={`grid h-9 w-9 place-items-center rounded-xl ${bg}`}><Icon size={17}/></div><p className="mt-4 text-xs font-medium text-slate-500">{title}</p><p className="mt-1 truncate text-xl font-bold tracking-tight">{value}</p><p className="mt-1 truncate text-xs text-slate-400">{foot}</p></article>}
function MiniCalendar({month,changeMonth,dayCount,offset,statusFor,onDay,selectedDay,freeDays}:{month:Date,changeMonth:(n:number)=>void,dayCount:number,offset:number,statusFor:(d:number)=>AnyObj,onDay:(d:number)=>void,selectedDay:number|null,freeDays:number[]}){return <div><div className="mb-3 flex items-center justify-between"><button onClick={()=>changeMonth(-1)} className="rounded-lg p-1 text-slate-400"><ChevronLeft size={17}/></button><span className="text-sm font-semibold capitalize">{dateFmt(month,{month:'long',year:'numeric'})}</span><button onClick={()=>changeMonth(1)} className="rounded-lg p-1 text-slate-400"><ChevronRight size={17}/></button></div><CalendarGrid dayCount={dayCount} offset={offset} statusFor={statusFor} onDay={onDay} selectedDay={selectedDay} compact freeDays={freeDays}/></div>}
function CalendarGrid({dayCount,offset,statusFor,onDay,selectedDay,compact=false,findFree=false,freeDays=[]}:{dayCount:number,offset:number,statusFor:(d:number)=>any,onDay:(d:number)=>void,selectedDay:number|null,compact?:boolean,findFree?:boolean,freeDays?:number[]}){return <div className="grid grid-cols-7 gap-y-1 text-center"><div className="col-span-7 mb-1 grid grid-cols-7">{['S','T','Q','Q','S','S','D'].map((d,i)=><span key={i} className="py-2 text-[10px] font-semibold text-slate-400">{d}</span>)}</div>{Array.from({length:offset},(_,i)=><span key={'e'+i}/>)}{Array.from({length:dayCount},(_,i)=>{const day=i+1,s=statusFor(day),highlight=freeDays.includes(day);return <button key={day} onClick={()=>onDay(day)} className={`relative mx-auto flex ${compact?'h-8 w-8 text-[11px]':'h-11 w-full max-w-[58px] flex-col text-sm'} items-center justify-center rounded-2xl font-medium transition ${selectedDay===day?'bg-sky-600 text-white shadow-md shadow-sky-200':findFree&&highlight?'bg-emerald-100 text-emerald-800':s?.state==='free'?'bg-emerald-50 text-emerald-700':s?.state==='busy'?'bg-rose-50 text-rose-700':'text-slate-700 hover:bg-slate-50'}`}><span>{day}</span>{!compact&&s?.total>0&&<span className="mt-0.5 text-[9px] opacity-70">{s.free}/{s.total}</span>}</button>})}</div>}
function Legend(){return <div className="mt-4 flex flex-wrap gap-x-4 gap-y-2 text-[11px] font-medium text-slate-500"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-emerald-500"/>Todos livres</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-sky-500"/>Parcial</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-rose-500"/>Todos ocupados</span></div>}
function People({people}:{people:AnyObj[]}){return <div className="mt-4 flex items-center">{people.slice(0,5).map((p,i)=><span key={p.id} className={i?' -ml-2 rounded-full ring-2 ring-white':''}><Avatar name={p.name} size="sm"/></span>)}<span className="ml-3 text-xs text-slate-500">{people.length} no grupo</span></div>}
function DayDetail({date,group,people,statusFor,selectedDay}:{date:Date,group:AnyObj,people:AnyObj[],statusFor:(d:number)=>any,selectedDay:number}){const s=statusFor(selectedDay);return <article className="rounded-[24px] bg-slate-50 p-4"><div className="mb-3 flex items-center justify-between"><div><p className="font-bold capitalize">{dateFmt(date,{day:'numeric',month:'long'})}</p><p className="mt-1 text-xs text-slate-500">{s?.free||0} de {s?.total||people.length} livres · {s?.busy||0} ocupados</p></div><span className="rounded-full bg-white px-3 py-1 text-xs font-semibold text-slate-600">{group?.name}</span></div><div className="space-y-2">{people.map((p:AnyObj)=>{const manual=group.availability.find((a:AnyObj)=>a.userId===p.id&&String(a.date).slice(0,10)===date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0'));const commitment=group.commitments.find((c:AnyObj)=>c.userId===p.id&&new Date(c.startsAt).toDateString()===date.toDateString());const busy=manual?.status==='BUSY'||commitment;return <div key={p.id} className="flex items-center gap-2 rounded-xl bg-white p-2.5"><Avatar name={p.name} size="sm"/><span className="flex-1 text-sm font-medium">{p.name}</span><span className={`text-xs font-semibold ${busy?'text-rose-600':'text-emerald-700'}`}>{busy?'Ocupado':'Livre'}</span></div>})}</div></article>}
function Modal({title,close,children}:{title:string,close:()=>void,children:React.ReactNode}){return <div onClick={close} className="fixed inset-0 z-50 flex items-end justify-center bg-slate-950/35 p-0 backdrop-blur-[2px] sm:items-center sm:p-5"><div onClick={e=>e.stopPropagation()} className="max-h-[90dvh] w-full overflow-y-auto rounded-t-[30px] bg-white p-5 shadow-2xl sm:max-w-lg sm:rounded-[30px] sm:p-7"><div className="mb-5 flex items-center justify-between"><h2 className="text-xl font-bold">{title}</h2><button onClick={close} className="grid h-9 w-9 place-items-center rounded-xl bg-slate-100 text-slate-500"><X size={18}/></button></div>{children}</div></div>}
function Empty({icon:Icon,title,action,onClick}:{icon:any,title:string,action:string,onClick:()=>void}){return <div className="grid min-h-72 place-items-center rounded-[28px] bg-white p-8 text-center"><div><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-sky-50 text-sky-700"><Icon size={24}/></div><h2 className="mt-4 font-bold">{title}</h2><Button className="mt-4" onClick={onClick}><Plus size={16}/>{action}</Button></div></div>}
function FinanceSummary({expenses,gross,people}:{expenses:AnyObj[],gross:number,people:AnyObj[]}){return <div className="grid gap-3 sm:grid-cols-3"><Stat icon={CircleDollarSign} title="Total gasto" value={money(gross)} foot={expenses.length+' lançamentos'} tone="sky"/><Stat icon={Users} title="Participantes" value={String(people.length)} foot="neste evento" tone="peach"/><Stat icon={Wallet} title="Média por pessoa" value={money(people.length?Math.round(gross/people.length):0)} foot="divisão geral" tone="mint"/></div>}
function MyFinancialSnapshot({events,userId}:{events:AnyObj[],userId:string}){let net=0;for(const event of events){for(const expense of event.expenses||[])for(const share of expense.participants||[]){if(share.userId===userId)net+=share.shareCents;if(expense.payerId===userId)net-=share.shareCents}for(const payment of event.payments||[])if(payment.status==='CONFIRMED'){if(payment.fromUserId===userId)net-=payment.amountCents;if(payment.toUserId===userId)net+=payment.amountCents}}const receive=Math.max(0,-net),owe=Math.max(0,net);return <article className="mt-4 rounded-[26px] bg-white p-5 shadow-sm"><p className="text-xs font-bold tracking-wider text-slate-400">MEU SALDO · EVENTOS DO GRUPO</p><div className="mt-3 grid grid-cols-3 gap-2"><div><p className="text-xs text-slate-500">A receber</p><p className="mt-1 text-sm font-bold text-emerald-700">{money(receive)}</p></div><div><p className="text-xs text-slate-500">Você deve</p><p className="mt-1 text-sm font-bold text-rose-600">{money(owe)}</p></div><div><p className="text-xs text-slate-500">Líquido</p><p className="mt-1 text-sm font-bold">{net<0?'+':''}{money(Math.abs(net))}</p></div></div></article>}
function NotificationCenter({items,unread,onRead}:{items:AnyObj[],unread:number,onRead:(id?:string)=>void}){const [filter,setFilter]=useState('ALL');const filtered=items.filter(n=>filter==='ALL'||(filter==='UNREAD'?!n.readAt:!!n.readAt));const icon=(type:string)=>type==='COMMITMENT'?'🗓️':type==='EVENT'?'🎉':type==='FINANCIAL'?'💸':type==='GROUP'?'👥':'✳️';return <><div className="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p className="text-sm text-slate-500">Fique por dentro dos planos</p><h1 className="mt-1 text-3xl font-bold tracking-tight">Notificações{unread>0&&<span className="ml-2 rounded-full bg-sky-100 px-2.5 py-1 align-middle text-sm text-sky-700">{unread}</span>}</h1></div>{unread>0&&<Button variant="soft" onClick={()=>onRead()}><Check size={16}/> Marcar todas como lidas</Button>}</div><div className="mb-4 flex gap-2">{[['ALL','Todas'],['UNREAD','Não lidas'],['READ','Lidas']].map(([v,label])=><button key={v} onClick={()=>setFilter(v)} className={`rounded-xl px-4 py-2 text-sm font-semibold ${filter===v?'bg-sky-600 text-white':'bg-white text-slate-500'}`}>{label}</button>)}</div><article className="divide-y divide-slate-100 rounded-[28px] bg-white px-5 shadow-sm">{filtered.map(n=><button key={n.id} onClick={()=>{if(!n.readAt)onRead(n.id);if(n.type==='GROUP'&&n.entityId)location.href='/convite/'+n.entityId}} className="flex w-full items-start gap-3 py-4 text-left transition hover:bg-slate-50"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-2xl bg-sky-50 text-lg">{icon(n.type)}</span><span className="min-w-0 flex-1"><span className="flex items-center gap-2 text-sm font-bold">{n.title}{!n.readAt&&<i className="h-2 w-2 rounded-full bg-sky-600"/>}</span><span className="mt-1 block text-sm leading-relaxed text-slate-600">{n.message}</span><span className="mt-2 block text-xs text-slate-400">{dateFmt(n.createdAt,{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})} · {n.type}</span></span></button>)}{!filtered.length&&<div className="grid min-h-52 place-items-center text-center"><div><Bell size={25} className="mx-auto text-slate-300"/><p className="mt-3 font-semibold text-slate-700">Tudo em dia</p><p className="mt-1 text-sm text-slate-400">Suas notificações aparecerão aqui.</p></div></div>}</article></>}
function AuditTimeline({items,eventId}:{items:AnyObj[],eventId?:string}){const rows=items.filter(a=>!eventId||a.eventId===eventId).slice(0,12);return <article className="rounded-[28px] bg-white p-5 shadow-sm"><h3 className="font-bold">Atividade recente</h3><div className="mt-3 space-y-3">{rows.map(a=><div key={a.id} className="flex gap-3 border-l-2 border-sky-100 pl-3"><span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-sky-500"/><div><p className="text-sm text-slate-700">{a.summary}</p><p className="mt-1 text-xs text-slate-400">{a.actor?.name||'casaê'} · {dateFmt(a.createdAt,{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</p></div></div>)}{!rows.length&&<p className="py-3 text-sm text-slate-400">As atividades do evento aparecerão aqui.</p>}</div></article>}
function InviteByEmail({group,act,notify}:{group:AnyObj,act:(a:string,v:AnyObj)=>Promise<any>,notify:(t:string)=>void}){return <form className="mt-5 border-t border-slate-100 pt-4" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await act('invite-member',{email:f.get('email')});notify('Convite enviado para a central da pessoa');e.currentTarget.reset()}catch(err:any){notify(err.message)}}}><p className="mb-2 text-sm font-semibold">Convidar alguém com conta casaê</p><div className="flex gap-2"><input name="email" type="email" required placeholder="amigo@email.com" className="min-w-0 flex-1 rounded-xl border border-slate-200 px-3 py-2 text-sm"/><button className="rounded-xl bg-sky-600 px-4 text-sm font-semibold text-white">Convidar</button></div><p className="mt-2 text-xs text-slate-400">Para quem ainda não tem conta, compartilhe o link do grupo.</p></form>}
function PreferencesForm({userId,notify,onTheme}:{userId:string,notify:(t:string)=>void,onTheme:(t:string)=>void}){const [prefs,setPrefs]=useState<AnyObj|null>(null),[push,setPush]=useState(false),[saving,setSaving]=useState(false),[installPrompt,setInstallPrompt]=useState<any>(null);useEffect(()=>{const handler=(e:any)=>{e.preventDefault();setInstallPrompt(e)};window.addEventListener('beforeinstallprompt',handler);return()=>window.removeEventListener('beforeinstallprompt',handler)},[]);useEffect(()=>{fetch('/api/preferences').then(r=>r.ok?r.json():null).then(p=>{if(p){setPrefs(p);setPush(p.pushEnabled)}})},[userId]);async function save(next:AnyObj){setSaving(true);const r=await fetch('/api/preferences',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(next)});if(r.ok){const p=await r.json();setPrefs(p);onTheme(p.theme);localStorage.setItem('junto-theme',p.theme.toLowerCase());notify('Preferências salvas')}else notify('Não foi possível salvar as preferências.');setSaving(false)}async function enablePush(){try{if(!('serviceWorker'in navigator)||!('PushManager'in window)){notify('Este navegador não oferece notificações push.');return}const permission=await Notification.requestPermission();if(permission!=='granted'){notify('Permita notificações nas configurações do navegador.');return}const registration=await navigator.serviceWorker.ready;const keyResponse=await fetch('/api/push/key');if(!keyResponse.ok)throw new Error('Push ainda não foi configurado no servidor.');const {key}=await keyResponse.json();const applicationServerKey=Uint8Array.from(atob(key.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-key.length%4)%4)),c=>c.charCodeAt(0));const subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey});const response=await fetch('/api/push/subscriptions',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(subscription)});if(!response.ok)throw new Error('Não foi possível ativar as notificações.');setPush(true);notify('Notificações push ativadas')}catch(e:any){notify(e.message||'Push não está disponível.')}}
if(!prefs)return <div className="mt-8 animate-pulse rounded-2xl bg-slate-100 p-8"/>;const toggle=(key:string)=>(e:React.ChangeEvent<HTMLInputElement>)=>save({...prefs,[key]:e.target.checked});return <section className="mt-8 border-t border-slate-100 pt-6"><h3 className="text-lg font-bold">Preferências</h3><p className="mt-1 text-sm text-slate-500">Escolha como o casaê acompanha seus planos.</p><div className="mt-4 space-y-3">{[['commitments','Compromissos'],['events','Eventos'],['financial','Financeiro'],['groups','Grupos']].map(([key,label])=><label key={key} className="flex items-center justify-between rounded-2xl bg-slate-50 px-4 py-3 text-sm font-medium"><span>{label}</span><input type="checkbox" checked={!!prefs[key]} onChange={toggle(key)} className="h-5 w-5 accent-sky-600"/></label>)}</div><label className="mt-4 block text-sm font-medium text-slate-600">Antecedência dos lembretes<select disabled={saving} value={prefs.reminderMinutes} onChange={e=>save({...prefs,reminderMinutes:Number(e.target.value)})} className="mt-1.5 w-full rounded-2xl border border-slate-200 bg-white px-4 py-3"><option value={15}>15 minutos</option><option value={30}>30 minutos</option><option value={60}>1 hora</option><option value={1440}>1 dia</option></select></label><div className="mt-5"><p className="text-sm font-semibold">Aparência</p><div className="mt-2 grid grid-cols-3 gap-2">{[['LIGHT','Claro',Sun],['DARK','Escuro',Moon],['SYSTEM','Automático',ShieldCheck]].map(([key,label,Icon]:any)=><button key={key} onClick={()=>save({...prefs,theme:key})} className={`flex items-center justify-center gap-2 rounded-2xl border px-2 py-3 text-xs font-semibold ${prefs.theme===key?'border-sky-300 bg-sky-50 text-sky-700':'border-slate-200 text-slate-500'}`}><Icon size={15}/>{label}</button>)}</div></div>{installPrompt&&<Button className="mb-4 w-full" onClick={async()=>{await installPrompt.prompt();setInstallPrompt(null)}}><Smartphone size={16}/> Instalar casaê</Button>}<div className="mt-5 rounded-2xl bg-slate-50 p-4"><div className="flex items-center justify-between gap-3"><div><p className="text-sm font-semibold">Notificações push</p><p className="mt-1 text-xs leading-relaxed text-slate-500">No iPhone, adicione o casaê à Tela de Início e abra pelo ícone para habilitar push (iOS 16.4+).</p></div><Button variant={push?'soft':'primary'} onClick={async()=>{if(!push){await enablePush();return}const sub=await (await navigator.serviceWorker.ready).pushManager.getSubscription();if(sub)await fetch('/api/push/subscriptions',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({endpoint:sub.endpoint})});setPush(false);notify('Notificações push desativadas')}}>{push?'Desativar':'Ativar'}</Button></div></div></section>}
function ExpenseList({expenses}:{expenses:AnyObj[]}){return <div className="mt-5 divide-y divide-slate-100">{expenses.map((e:AnyObj)=><div key={e.id} className="py-4"><div className="flex items-start justify-between"><div><p className="font-semibold">{e.description}</p><p className="mt-1 text-xs text-slate-500">{dateFmt(e.spentAt,{day:'2-digit',month:'short'})} · pago por {e.payer.name}</p></div><p className="font-bold">{money(e.amountCents)}</p></div><div className="mt-3 flex flex-wrap gap-2">{e.participants.map((p:AnyObj)=><span key={p.id} className="rounded-full bg-slate-50 px-2.5 py-1 text-[11px] text-slate-600">{p.user.name} · {money(p.shareCents)}</span>)}</div></div>)}{expenses.length===0&&<p className="py-6 text-sm text-slate-500">Adicione a primeira despesa do evento.</p>}</div>}
function NetBalances({expenses,payments,eventId,people,me,act,notify}:{expenses:AnyObj[],payments:AnyObj[],eventId:string,people:AnyObj[],me:string,act:(a:string,v:AnyObj)=>Promise<any>,notify:(t:string)=>void}){const [pix,setPix]=useState<AnyObj|null>(null);const bal=new Map<string,number>();for(const e of expenses)for(const s of e.participants){bal.set(s.userId,(bal.get(s.userId)||0)+s.shareCents);bal.set(e.payerId,(bal.get(e.payerId)||0)-s.shareCents)}for(const p of payments.filter(p=>p.status==='CONFIRMED')){bal.set(p.fromUserId,(bal.get(p.fromUserId)||0)-p.amountCents);bal.set(p.toUserId,(bal.get(p.toUserId)||0)+p.amountCents)}const debtors=[...bal].filter(([,v])=>v>0).map(([id,c])=>({id,c})),creditors=[...bal].filter(([,v])=>v<0).map(([id,c])=>({id,c:-c}));const debts:{from:string;to:string;c:number}[]=[];let i=0,j=0;while(i<debtors.length&&j<creditors.length){const c=Math.min(debtors[i].c,creditors[j].c);if(c)debts.push({from:debtors[i].id,to:creditors[j].id,c});debtors[i].c-=c;creditors[j].c-=c;if(!debtors[i].c)i++;if(!creditors[j].c)j++}return <article className="mt-5 rounded-[28px] bg-white p-5 shadow-sm sm:p-7"><h2 className="font-bold">Saldos após compensação</h2><p className="mt-1 text-sm text-slate-500">Somente os valores líquidos; o histórico original continua disponível.</p><div className="mt-4 space-y-2">{debts.map((d,k)=>{const from=people.find(p=>p.id===d.from),to=people.find(p=>p.id===d.to),pending=payments.filter(p=>p.status==='PENDING'&&p.fromUserId===d.from&&p.toUserId===d.to);return <div key={k} className="flex flex-wrap items-center gap-3 rounded-2xl bg-slate-50 p-3"><Avatar name={from?.name||'?'} size="sm"/><div className="min-w-0 flex-1"><p className="text-sm"><b>{from?.name}</b> deve para <b>{to?.name}</b></p><p className="text-xs text-slate-500">{pending.length?'Aguardando confirmação de '+money(pending.reduce((sum:number,p:AnyObj)=>sum+p.amountCents,0)):'Em aberto'}</p></div><b className="text-sm">{money(d.c)}</b>{me===d.from&&<><button onClick={async()=>{const amount=prompt('Quanto você pagou? Saldo: '+money(d.c));if(!amount)return;const cents=Math.round(Number(amount.replace(',','.'))*100);if(!Number.isFinite(cents)||cents<1||cents>d.c){notify('Valor inválido para o saldo atual.');return}try{await act('payment',{eventId,toUserId:d.to,amountCents:cents});notify('Pagamento enviado para confirmação')}catch(e:any){notify(e.message)}}} className="rounded-xl bg-sky-100 px-3 py-2 text-xs font-semibold text-sky-700">Marcar pago</button><button aria-label="Gerar QR Code Pix" onClick={async()=>{const r=await fetch('/api/pix',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({eventId,toUserId:d.to,amountCents:d.c})});const j=await r.json();if(!r.ok){notify(j.error);return}setPix(j)}} className="rounded-xl bg-slate-100 p-2 text-slate-600"><QrCode size={16}/></button></>}{me===d.to&&pending.map((payment:AnyObj)=><span key={payment.id} className="flex gap-1"><button onClick={async()=>{try{await act('confirm-payment',{paymentId:payment.id});notify('Recebimento confirmado')}catch(e:any){notify(e.message)}}} className="rounded-xl bg-emerald-100 px-3 py-2 text-xs font-semibold text-emerald-800">Confirmar {money(payment.amountCents)}</button><button onClick={async()=>{try{await act('reject-payment',{paymentId:payment.id});notify('Pagamento rejeitado')}catch(e:any){notify(e.message)}}} className="rounded-xl bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-700">Rejeitar</button></span>)}</div>})}{!debts.length&&<p className="rounded-2xl bg-emerald-50 p-4 text-sm font-medium text-emerald-800">Tudo equilibrado por aqui ✨</p>}</div>{pix&&<div className="fixed inset-0 z-[70] grid place-items-center bg-slate-950/40 p-4" onClick={()=>setPix(null)}><article className="w-full max-w-sm rounded-[28px] bg-white p-6 text-center shadow-2xl" onClick={e=>e.stopPropagation()}><button className="float-right rounded-xl bg-slate-100 p-2" onClick={()=>setPix(null)}><X size={17}/></button><h3 className="text-xl font-bold">Pague com Pix</h3><p className="mt-2 text-slate-500">{pix.receiverName} · {money(pix.amountCents)}</p><img src={pix.qrCode} alt="QR Code Pix" className="mx-auto my-5 h-64 w-64"/><p className="break-all rounded-xl bg-slate-50 p-3 text-left text-xs text-slate-600">{pix.pixKey}</p><Button className="mt-3 w-full" onClick={async()=>{await navigator.clipboard?.writeText(pix.payload);notify('Pix copia e cola copiado')}}><Copy size={16}/> Copiar Pix copia e cola</Button><p className="mt-3 text-xs text-slate-400">O casaê não movimenta dinheiro.</p></article></div>}</article>}

function EventFinance({event,expenses,gross,people,act,notify}:{event:AnyObj,expenses:AnyObj[],gross:number,people:AnyObj[],act:(a:string,v:AnyObj)=>Promise<any>,notify:(t:string)=>void}){return <div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><article className="rounded-[28px] bg-white p-5 shadow-sm sm:p-6"><div className="flex items-center justify-between"><h3 className="font-bold">Despesas do evento</h3><span className="rounded-full bg-sky-50 px-3 py-1 text-xs font-semibold text-sky-700">{expenses.length} lançamentos</span></div><ExpenseList expenses={expenses}/><Button variant="soft" className="mt-2 w-full" onClick={()=>notify('Use Gastos para registrar uma despesa.') }><Plus size={16}/> Registrar gasto</Button></article><div><FinanceSummary expenses={expenses} gross={gross} people={people}/><NetBalances expenses={expenses} payments={event.payments||[]} eventId={event.id} people={people} me="" act={act} notify={notify}/></div></div>}
function ProfileForm({user,act,notify}:{user:AnyObj,act:(a:string,v:AnyObj)=>Promise<any>,notify:(t:string)=>void}){return <form className="mt-7 grid gap-4 sm:grid-cols-2" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await act('profile',Object.fromEntries(f.entries()));notify('Perfil atualizado')}catch(err:any){notify(err.message)}}}><Field label="Nome" name="name" defaultValue={user.name}/><Field label="WhatsApp" name="whatsapp" defaultValue={user.whatsapp||''} placeholder="(11) 99999-9999"/><label className="text-sm font-medium text-slate-600">Tipo da chave Pix<select name="pixType" defaultValue={user.pixType||'RANDOM'} className="mt-1.5 w-full rounded-2xl border border-slate-200 bg-white px-4 py-3"><option value="CPF">CPF</option><option value="CNPJ">CNPJ</option><option value="EMAIL">E-mail</option><option value="PHONE">Telefone</option><option value="RANDOM">Aleatória</option></select></label><Field label="Chave Pix (opcional)" name="pixKey" defaultValue={user.pixKey||''} placeholder="Sua chave para facilitar acertos"/><div className="sm:col-span-2"><Button>Salvar perfil</Button></div></form>}
function GroupForm({act,refresh,notify,onDone}:{act:(a:string,v:AnyObj)=>Promise<any>,refresh:()=>void,notify:(t:string)=>void,onDone:()=>void}){return <form className="space-y-4" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await act('create-group',{name:f.get('name'),description:f.get('description'),emoji:f.get('emoji')});await refresh();notify('Grupo criado!');onDone()}catch(err:any){notify(err.message)}}}><Field label="Nome do grupo" name="name" required placeholder="Amigos, viagem, churrasco..."/><Field label="Descrição" name="description" placeholder="Um grupo para combinar os próximos planos"/><Field label="Emoji" name="emoji" defaultValue="👋"/><Button className="w-full">Criar grupo</Button><p className="text-center text-xs text-slate-400">Já tem um convite? <button type="button" onClick={async()=>{const code=prompt('Cole o código ou link do convite');if(code)try{await act('join-group',{code:code.split('/').pop()});await refresh();notify('Você entrou no grupo!');onDone()}catch(e:any){notify(e.message)}}} className="font-semibold text-sky-700">Entrar com convite</button></p></form>}
function CommitmentForm({act,notify,onDone}:{act:(a:string,v:AnyObj)=>Promise<any>,notify:(t:string)=>void,onDone:()=>void}){return <form className="space-y-4" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await act('commitment',{title:f.get('title'),startsAt:new Date(String(f.get('startsAt'))).toISOString(),endsAt:f.get('endsAt')?new Date(String(f.get('endsAt'))).toISOString():undefined,location:f.get('location'),description:f.get('description'),allDay:f.get('allDay')==='on',recurrence:f.get('recurrence')});notify('Compromisso adicionado');onDone()}catch(err:any){notify(err.message)}}}><Field label="Título" name="title" required placeholder="Dentista, academia..."/><Field label="Início" name="startsAt" type="datetime-local" required/><Field label="Fim" name="endsAt" type="datetime-local"/><Field label="Local" name="location" placeholder="Opcional"/><label className="block text-sm text-slate-600">Recorrência<select name="recurrence" className="mt-1 w-full rounded-2xl border border-slate-200 px-4 py-3"><option value="NEVER">Nunca</option><option value="DAILY">Diariamente</option><option value="WEEKLY">Semanalmente</option><option value="MONTHLY">Mensalmente</option><option value="YEARLY">Anualmente</option></select></label><label className="flex items-center gap-2 text-sm text-slate-600"><input type="checkbox" name="allDay"/> Dia inteiro</label><label className="block text-sm text-slate-600">Descrição<textarea name="description" className="mt-1 w-full rounded-2xl border border-slate-200 p-3" rows={2}/></label><Button className="w-full">Salvar compromisso</Button></form>}
function EventForm({act,notify,onDone}:{act:(a:string,v:AnyObj)=>Promise<any>,notify:(t:string)=>void,onDone:()=>void}){return <form className="space-y-4" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await act('event',{title:f.get('title'),startsAt:new Date(String(f.get('startsAt'))).toISOString(),endsAt:f.get('endsAt')?new Date(String(f.get('endsAt'))).toISOString():undefined,location:f.get('location'),emoji:f.get('emoji')});notify('Evento criado');onDone()}catch(err:any){notify(err.message)}}}><Field label="Nome do evento" name="title" required placeholder="Réveillon no Rio 🎆"/><Field label="Começa em" name="startsAt" type="datetime-local" required/><Field label="Termina em" name="endsAt" type="datetime-local"/><Field label="Local" name="location" placeholder="Rio de Janeiro"/><Field label="Emoji" name="emoji" defaultValue="🎉"/><Button className="w-full">Criar evento</Button></form>}
function ExpenseForm({event,people,act,notify,onDone}:{event:AnyObj,people:AnyObj[],act:(a:string,v:AnyObj)=>Promise<any>,notify:(t:string)=>void,onDone:()=>void}){const [split,setSplit]=useState('EQUAL');return <form className="space-y-4" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const ids=f.getAll('participantIds').map(String);const shares=ids.map(id=>Number(f.get('share-'+id)||0));try{await act('expense',{eventId:event.id,description:f.get('description'),amountCents:Math.round(Number(String(f.get('amount')).replace(',','.'))*100),category:f.get('category'),spentAt:f.get('spentAt')?new Date(String(f.get('spentAt'))+'T12:00:00').toISOString():undefined,participantIds:ids,splitType:split,...(split==='EQUAL'?{}:{shares})});notify(split==='EQUAL'?'Despesa dividida igualmente':'Despesa com divisão personalizada salva');onDone()}catch(err:any){notify(err.message)}}}><Field label="O que foi?" name="description" required placeholder="Hotel, jantar..."/><Field label="Valor (R$)" name="amount" type="number" step="0.01" min="0.01" required placeholder="0,00"/><Field label="Data" name="spentAt" type="date"/><label className="block text-sm text-slate-600">Categoria<select name="category" className="mt-1 w-full rounded-2xl border border-slate-200 px-4 py-3">{[['LODGING','Hospedagem'],['TRANSPORT','Transporte'],['FOOD','Alimentação'],['DRINKS','Bebidas'],['TOURS','Passeios'],['TICKETS','Ingressos'],['FUEL','Combustível'],['SHOPPING','Compras'],['OTHER','Outros']].map(x=><option value={x[0]} key={x[0]}>{x[1]}</option>)}</select></label><label className="block text-sm text-slate-600">Tipo de divisão<select value={split} onChange={e=>setSplit(e.target.value)} className="mt-1 w-full rounded-2xl border border-slate-200 px-4 py-3"><option value="EQUAL">Igual</option><option value="VALUE">Por valor</option><option value="PERCENT">Por porcentagem</option></select></label><p className="text-sm font-semibold text-slate-600">Participantes e divisão</p><div className="space-y-2">{(event.members||[]).map((m:AnyObj)=><label key={m.user.id} className="flex items-center gap-2 rounded-xl bg-slate-50 p-2.5 text-sm"><input type="checkbox" name="participantIds" value={m.user.id} defaultChecked/><span className="flex-1">{m.user.name}</span>{split!=='EQUAL'&&<input name={'share-'+m.user.id} aria-label={split==='VALUE'?'Valor em reais':'Porcentagem'} type="number" min="0" step="0.01" placeholder={split==='VALUE'?'R$':'%'} className="w-24 rounded-xl border border-slate-200 bg-white px-2 py-1.5 text-right text-sm"/>}</label>)}</div>{split!=='EQUAL'&&<p className="rounded-xl bg-sky-50 p-3 text-xs text-sky-800">A soma precisa corresponder ao total da despesa{split==='PERCENT'?' (100%)':'.'}</p>}<Button className="w-full">Salvar gasto</Button></form>}
